    for no in range(16, 26):
        k = f"n{no}"; old = MP.load()[k]; rel = LP.REL_FIX[k]; b = build(no)
        MP.add(k, D.datetime.fromisoformat(old["dt"]), old["title"], old["tags"], MP.blocks_from_html(to_html_imgs(b)), related={"id": rel[0], "phrase": rel[1]}, category=old.get("category"), thumbs=old.get("thumbs"), cid=old.get("cid"), clips=old.get("clips"))
